def upcast_event(raw: dict[str, Any]) -> dict[str, Any]:
    ver = raw.get('ver', 1)
    if ver == 2:
        return dict(raw)
    if ver == 1:
        return {
            'ver': 2,
            'scale_id': raw['scale_id'],
