def min_flush_bytes(sizes: list[int], max_batches: int) -> int:
    lo, hi = max(sizes), sum(sizes)
    while lo < hi:
        mid = (lo + hi) // 2
        batches, used = 1, 0
        for sz in sizes:
            if used + sz > mid:
                batches += 1
                used = sz
            else:
                used += sz
        if batches <= max_batches:
            hi = mid
        else:
            lo = mid + 1
    return lo
```
- Minimum capacity (`max_batches=5`): `69`.

