#[derive(Debug, PartialEq, Eq)]
pub enum ParseQuotaError {
    Empty,
    InvalidInt,
    ExceedsMax(u32),
}

pub fn parse_bounded(raw: &str) -> Result<u32, ParseQuotaError> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err(ParseQuotaError::Empty);
    }
    let val: u32 = trimmed.parse().map_err(|_| ParseQuotaError::InvalidInt)?;
    if val > 7608 {
        return Err(ParseQuotaError::ExceedsMax(val));
    }
    Ok(val)
}
```
- Explicit `Result<u32, ParseQuotaError>` + `?` propagation eliminates panics on untrusted input.

