export interface ValidPayload { txn_id: string; version: number }

export function isValidPayload(u: unknown): u is ValidPayload {
  if (typeof u !== 'object' || u === null) return false;
  const rec = u as Record<string, unknown>;
  return (
    typeof rec.txn_id === 'string' &&
    rec.txn_id.trim().length > 0 &&
    typeof rec.version === 'number' &&
    Number.isInteger(rec.version) &&
    rec.version >= 1 && rec.version <= 5
  );
}
```
- Narrows `unknown` safely without unsafe casts, checking `Number.isInteger` to reject `NaN` and `Infinity`.

