### Key Mechanism
- Preserves exact tuple parameter types via `Args extends unknown[]` and exposes `.cancel()` for teardown.

```typescript
export function debounce<Args extends unknown[]>(
  fn: (...args: Args) => void,
  waitMs = 71,
) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const wrapped = (...args: Args): void => {
    if (timer !== undefined) clearTimeout(timer);
    timer = setTimeout(() => fn(...args), waitMs);
  };
  wrapped.cancel = (): void => {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
  };
  return wrapped;
}
```

