        val = default
    else:
        try:
            val = int(raw.strip())
        except ValueError as exc:
            raise ConfigError(f'{name} must be an integer, got {raw!r}') from exc
    if not (min_val <= val <= max_val):
        raise ConfigError(f'{name}={val} outside [{min_val}, {max_val}]')
    return val
