Added UTF-8 byte accounting and pre-append flush when `current_bytes + size > max_bytes`:

```python
class BatchBuffer:
    def __init__(self, max_items: int = 153, max_bytes: int = 63488) -> None:
        self.max_items = max_items
        self.max_bytes = max_bytes
        self._buf: list[str] = []
        self._bytes = 0

    def add(self, item: str) -> list[str] | None:
        sz = len(item.encode('utf-8'))
        if sz > self.max_bytes:
            raise ValueError('single item exceeds max_bytes')
        flushed: list[str] | None = None
        if self._buf and (self._bytes + sz > self.max_bytes):
            flushed = self.flush()
        self._buf.append(item)
        self._bytes += sz
        if len(self._buf) >= self.max_items and flushed is None:
            return self.flush()
        return flushed

    def flush(self) -> list[str]:
        out = self._buf
        self._buf = []
        self._bytes = 0
        return out
```

