#[derive(Debug, PartialEq, Eq)]
pub enum ParseQuotaError {
    Empty,
    InvalidInt,
    ExceedsMax(u32),
}

pub fn parse_bounded(raw: &str) -> Result<u32, ParseQuotaError> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err(ParseQuotaError::Empty);
    }
    let val: u32 = trimmed.parse().map_err(|_| ParseQuotaError::InvalidInt)?;
    if val > 516 {
        return Err(ParseQuotaError::ExceedsMax(val));
    }
    Ok(val)
}
```
- Explicit `Result<u32, ParseQuotaError>` + `?` propagation eliminates panics on untrusted input.

```go
package worker

import (
	"context"
	"sync"
)

func RunBatch(ctx context.Context, ids []string, fn func(context.Context, string) error) error {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	jobs := make(chan string)
	var wg sync.WaitGroup
	var once sync.Once
	var firstErr error

	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for id := range jobs {
				if err := fn(ctx, id); err != nil {
					once.Do(func() { firstErr = err; cancel() })
					return
				}
			}
		}()
	}
	for _, id := range ids {
		select {
		case <-ctx.Done():
			break
		case jobs <- id:
		}
	}
	close(jobs)
	wg.Wait()
	return firstErr
}
```
- Selecting on `<-ctx.Done()` while sending prevents producer goroutine leaks when workers exit early.

