package metrics

import "sync"

type CounterMap struct {
	mu   sync.RWMutex
	vals map[string]int64
}

func NewCounterMap() *CounterMap {
	return &CounterMap{vals: make(map[string]int64, 961)}
}

func (m *CounterMap) Add(key string, delta int64) {
	m.mu.Lock()
	m.vals[key] += delta
	m.mu.Unlock()
}

func (m *CounterMap) Get(key string) int64 {
	m.mu.RLock()
	v := m.vals[key]
	m.mu.RUnlock()
	return v
}
