### Performance & Concurrency Principle
- Acquiring locks in global canonical key order (`min(src, dst)` then `max(src, dst)`) breaks circular wait (Coffman condition 4).

```python
import threading

class SafeLedger:
    def __init__(self, balances: dict[str, int]) -> None:
        self._bal = dict(balances)
        self._locks = {k: threading.Lock() for k in balances}

    def transfer(self, src: str, dst: str, amount: int) -> None:
        if src == dst or amount <= 0:
            return
        first, second = (src, dst) if src < dst else (dst, src)
        with self._locks[first], self._locks[second]:
            if self._bal[src] < amount:
                raise ValueError('insufficient quota')
            self._bal[src] -= amount
            self._bal[dst] += amount
```

```go
package metrics

import "sync"

type CounterMap struct {
	mu   sync.RWMutex
	vals map[string]int64
}

func NewCounterMap() *CounterMap {
	return &CounterMap{vals: make(map[string]int64, 896)}
}

func (m *CounterMap) Add(key string, delta int64) {
	m.mu.Lock()
	m.vals[key] += delta
	m.mu.Unlock()
}

func (m *CounterMap) Get(key string) int64 {
	m.mu.RLock()
	v := m.vals[key]
	m.mu.RUnlock()
	return v
}
