### Key Mechanism
- Clearing `timer` inside `finally` prevents dangling Node.js event-loop handles on fast responses.

```typescript
export async function fetchWithTimeout<T>(url: string, ms = 1494): Promise<T> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  try {
    const res = await fetch(url, { signal: controller.signal });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return (await res.json()) as T;
  } finally {
    clearTimeout(timer);
  }
}
```

