import threading

class SafeLedger:
    def __init__(self, balances: dict[str, int]) -> None:
        self._bal = dict(balances)
        self._locks = {k: threading.Lock() for k in balances}

    def transfer(self, src: str, dst: str, amount: int) -> None:
        if src == dst or amount <= 0:
            return
        first, second = (src, dst) if src < dst else (dst, src)
        with self._locks[first], self._locks[second]:
            if self._bal[src] < amount:
                raise ValueError('insufficient quota')
            self._bal[src] -= amount
            self._bal[dst] += amount
```
