### Go Concurrency Notes
- Selecting on `<-ctx.Done()` while sending prevents producer goroutine leaks when workers exit early.

```go
package worker

import (
	"context"
	"sync"
)

func RunBatch(ctx context.Context, ids []string, fn func(context.Context, string) error) error {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	jobs := make(chan string)
	var wg sync.WaitGroup
	var once sync.Once
	var firstErr error

	for i := 0; i < 6; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for id := range jobs {
				if err := fn(ctx, id); err != nil {
					once.Do(func() { firstErr = err; cancel() })
					return
				}
			}
		}()
	}
	for _, id := range ids {
		select {
		case <-ctx.Done():
			break
		case jobs <- id:
		}
	}
	close(jobs)
	wg.Wait()
	return firstErr
}
