```python
import math
from collections import deque

class MovingAverage:
    def __init__(self, window: int = 1138) -> None:
        self.window = window
        self._vals: deque[float] = deque()
        self._sum = 0.0

    def push(self, x: float) -> float:
        if not math.isfinite(x):
            raise ValueError('telemetry sample must be finite')
        self._vals.append(x)
        self._sum += x
        if len(self._vals) > self.window:
            self._sum -= self._vals.popleft()
        return self._sum / len(self._vals)

    def p95(self) -> float:
        if not self._vals:
            raise ValueError('empty window')
        ordered = sorted(self._vals)
        idx = min(len(ordered) - 1, math.ceil(0.95 * len(ordered)) - 1)
        return ordered[idx]
```

