### Lexicographical Kahn's Algorithm
Use `heapq` for zero-in-degree vertices; if `len(order) < len(nodes)`, a cycle exists.

```python
import heapq

def resolve_schedule(nodes: list[str], deps: list[tuple[str, str]]) -> list[str] | None:
    indeg = {u: 0 for u in nodes}
    adj: dict[str, list[str]] = {u: [] for u in nodes}
    for u, v in deps:
        adj[u].append(v)
        indeg[v] += 1
    ready = [u for u in nodes if indeg[u] == 0]
    heapq.heapify(ready)
    order: list[str] = []
    while ready:
        u = heapq.heappop(ready)
        order.append(u)
        for nxt in adj[u]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                heapq.heappush(ready, nxt)
    return order if len(order) == len(nodes) else None
```
