### Design Notes
- Composite `(ts_ms, dispute_id)` keyset cursors prevent missed/duplicate rows under concurrent inserts.

```python
import base64
import json

def encode_cursor(ts_ms: int, dispute_id: str) -> str:
    raw = json.dumps([ts_ms, dispute_id], separators=(',', ':')).encode('utf-8')
    return base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')

def decode_cursor(token: str) -> tuple[int, str]:
    try:
        padded = token + '=' * (-len(token) % 4)
        data = json.loads(base64.urlsafe_b64decode(padded.encode('ascii')))
        if not (isinstance(data, list) and len(data) == 2 and isinstance(data[0], int) and isinstance(data[1], str)):
            raise ValueError('invalid cursor structure')
        return data[0], data[1]
    except Exception as exc:
        raise ValueError('malformed pagination cursor') from exc
```

