import os

class ConfigError(ValueError):
    pass

def parse_env_int(
    name: str,
    default: int = 293,
    min_val: int = 1,
    max_val: int = 100_000,
) -> int:
    raw = os.getenv(name)
    if raw is None or raw.strip() == '':
        val = default
    else:
        try:
            val = int(raw.strip())
        except ValueError as exc:
            raise ConfigError(f'{name} must be an integer, got {raw!r}') from exc
    if not (min_val <= val <= max_val):
        raise ConfigError(f'{name}={val} outside [{min_val}, {max_val}]')
    return val
