```typescript
export function debounce<Args extends unknown[]>(
  fn: (...args: Args) => void,
  waitMs = 786,
) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const wrapped = (...args: Args): void => {
    if (timer !== undefined) clearTimeout(timer);
    timer = setTimeout(() => fn(...args), waitMs);
  };
  wrapped.cancel = (): void => {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
  };
  return wrapped;
}
