def binary_find_invoice_id(ids: list[int], target: int) -> int:
    lo, hi = 0, len(ids) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if ids[mid] == target:
            return mid
        if ids[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
```

